let currentUser=null,needsSetup=false,routeVersion=0;
async function api(url,method='GET',body){const r=await fetch('/api/'+url,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw new Error(data.error||'Não foi possível carregar.');return data;}
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const notice='<div class="account-notice">PRÉVIA DA LOJA · Pedidos de demonstração, sem cobrança ou envio.</div>';
const dateLabel=d=>new Date(d).toLocaleDateString('pt-BR');
function authView(admin=false,register=false){const setup=admin&&needsSetup;return `<section class="auth-layout ${admin?'admin-auth':''}"><div class="auth-intro"><div class="eyebrow">${admin?'GESTÃO MS ATACADO':'SUA CONTA MS'}</div><h1>${admin?'Sua loja.<br>Em um só lugar.':'Seu próximo<br>pedido começa<br>com você.'}</h1><p>${admin?'Organize o catálogo, acompanhe pedidos e conheça seus clientes.':'Salve suas seleções de jeans e encontre seus pedidos sempre que precisar.'}</p><img src="assets/hero.webp" alt="Jeans dobrados em uma mesa"></div><div class="auth-panel"><div class="eyebrow">${setup?'PRIMEIRO ACESSO':register?'BEM-VINDO À MS':'BOM TER VOCÊ AQUI'}</div><h2>${setup?'Criar administrador':register?'Crie sua conta':admin?'Entrar no painel':'Entrar na minha conta'}</h2><p>${setup?'Defina o e-mail e a senha de acesso ao painel local.':admin?'Entre com os dados definidos ao criar o administrador.':'Use seu e-mail e sua senha para continuar.'}</p><form data-account-form="${setup?'setup':register?'register':'login'}" data-admin="${admin}">${setup||register?field('Seu nome','name','','text','required minlength="2" maxlength="100" autocomplete="name"'):''}${field('E-mail','email','','email','required maxlength="160" autocomplete="username"')}${field('Senha','password','','password',`required minlength="10" maxlength="128" autocomplete="${register||setup?'new-password':'current-password'}"`)}<small>Mínimo de 10 caracteres.</small><p class="form-error" role="alert"></p><button class="btn dark" type="submit">${setup?'Criar acesso administrativo':register?'Criar minha conta':'Entrar'} ↗</button></form>${admin?'':`<p>${register?'Já tem uma conta? <a href="#conta">Entrar</a>':'Primeira vez por aqui? <a href="#cadastro">Criar conta</a>'}</p>`}<a class="text-link" href="#catalogo">Voltar ao catálogo</a>${notice}</div></section>`;}
function shell(title,subtitle,content,admin=false){const base=admin?'admin':'conta';const links=admin?[['admin','Visão geral'],['admin/pedidos','Pedidos'],['admin/produtos','Catálogo'],['admin/clientes','Clientes']]:[['conta','Meus pedidos'],['conta/dados','Meus dados']];return `<div class="workspace"><aside class="account-sidebar"><div class="eyebrow">${admin?'PAINEL ADMINISTRATIVO':'MINHA CONTA'}</div><strong>${esc(currentUser.name)}</strong><small>${esc(currentUser.email)}</small><nav aria-label="Menu da conta">${links.map(([href,label])=>`<a class="${location.hash==='#'+href?'selected':''}" href="#${href}">${label}<span>↗</span></a>`).join('')}</nav><a href="#catalogo">Ir para a loja ↗</a>${currentUser.role==='admin'&&!admin?'<a href="#admin">Painel administrativo ↗</a>':''}<button class="logout" data-logout>Sair da conta</button></aside><section class="account-content"><div class="eyebrow">MS ATACADO / ${admin?'GESTÃO':'ÁREA DO CLIENTE'}</div><h1>${title}</h1><p class="muted">${subtitle}</p>${notice}${content}</section></div>`;}
function orderCards(orders,admin=false){return orders.length?orders.map(o=>`<article class="order-card"><div class="order-heading"><div><strong>Pedido #${o.id.slice(0,8).toUpperCase()}</strong><small>${dateLabel(o.created)} · ${o.items.reduce((s,i)=>s+i.qty,0)} peças · Simulação</small>${admin?`<p>${esc(o.name)} · ${esc(o.email)}</p>`:''}</div><span class="status-pill">${esc(o.status)}</span></div><details><summary>Ver peças do pedido</summary>${o.items.map(i=>`<div class="order-item"><img src="${productImage(i.image)}" alt=""><div><strong>${esc(i.name)}</strong><p>Tamanho ${esc(i.size)} · ${i.qty} peças</p></div><span>Preço a definir</span></div>`).join('')}<p class="muted">Sem pagamento realizado. Frete e valores não calculados.</p></details>${admin?`<form data-status="${o.id}" class="status-form"><label>Situação <select name="status">${['Salvo','Em análise','Concluído','Cancelado'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></label><button class="btn outline">Atualizar</button><span class="form-error" role="alert"></span></form>`:''}</article>`).join(''):'<div class="account-empty"><span class="empty-number">06</span><h2>A próxima seleção começa aqui.</h2><p>Nenhum pedido salvo por enquanto.</p><a class="btn" href="#catalogo">Explorar catálogo ↗</a></div>';}
const originalRoute=route;
window.removeEventListener('hashchange',originalRoute);
route=async function(){const version=++routeVersion;const page=location.hash.slice(1)||'inicio';if(!/^(conta|cadastro|admin)(\/|$)/.test(page)){try{await loadProducts();if(version===routeVersion)originalRoute();}catch(e){toast(e.message);}return;}main.innerHTML='<section class="info-page"><p role="status">Carregando sua área…</p></section>';window.scrollTo(0,0);try{const session=await api('session');if(version!==routeVersion)return;currentUser=session.user;needsSetup=session.setupNeeded;const admin=page.startsWith('admin');document.title='MS Atacado — '+(admin?'Painel administrativo':'Minha conta');if(!currentUser||(admin&&needsSetup)){main.innerHTML=authView(admin,page==='cadastro');return;}if(admin&&currentUser.role!=='admin'){main.innerHTML=shell('Acesso restrito','Esta conta não tem acesso ao painel da MS.','<a class="btn" href="#conta">Ir para minha conta</a>');return;}
 if(admin){await loadProducts();const data=await api('admin/overview');if(version!==routeVersion)return;let content,title,subtitle;
 if(page==='admin/produtos'){title='Seu catálogo.';subtitle='Edite os modelos demonstrativos exibidos na loja.';content=`<div class="admin-products">${products.map(p=>`<form class="product-editor" data-product="${p.id}"><img src="${productImage(p.image)}" alt="${esc(p.name)}"><div>${field('Nome do modelo','name',p.name,'text','required minlength="2" maxlength="100"')}<label class="field">Categoria<select name="type">${['Calças','Shorts'].map(t=>`<option ${p.type===t?'selected':''}>${t}</option>`).join('')}</select></label>${field('Lavagem','wash',p.wash,'text','required minlength="2" maxlength="80"')}<label class="field">Descrição<textarea name="description" required minlength="10" maxlength="1500">${esc(p.description)}</textarea></label>${photoEditor(p)}${stockEditor(p)}<p class="muted">Preços ainda não definidos. Produtos demonstrativos.</p><p class="form-error" role="alert"></p><button class="btn dark">Salvar alterações</button></div></form>`).join('')}</div>`;}
 else if(page==='admin/clientes'){title='Quem compra com você.';subtitle='Clientes cadastrados neste ambiente local.';content=data.customers.length?`<div class="customer-list">${data.customers.map(c=>`<article class="order-card"><strong>${esc(c.name)}</strong><p>${esc(c.email)}</p><small>Cadastro em ${dateLabel(c.created)} · ${data.orders.filter(o=>o.user_id===c.id).length} pedidos salvos</small></article>`).join('')}</div>`:'<div class="account-empty"><h2>Seus clientes aparecerão aqui.</h2><p>Novos cadastros entram automaticamente nesta lista.</p></div>';}
 else if(page==='admin/pedidos'){title='Cada pedido, de perto.';subtitle='Acompanhe as seleções e atualize a situação de cada uma.';content=orderCards(data.orders,true);}
 else{title='Visão geral.';subtitle='Uma visão do que acontece na sua loja.';content=`<div class="stats"><article><span>Pedidos salvos</span><strong>${data.orders.length}</strong><small>Simulações locais</small></article><article><span>Clientes</span><strong>${data.customers.length}</strong><small>Contas cadastradas</small></article><article><span>Modelos no catálogo</span><strong>${products.length}</strong><small>Produtos ilustrativos</small></article></div><div class="dashboard-banner"><h2>Pronta para o próximo pedido.</h2><p>Catálogo organizado e clientes por perto.</p><a class="btn" href="#admin/produtos">Gerenciar catálogo ↗</a></div><h2>Pedidos recentes</h2>${orderCards(data.orders.slice(0,3),true)}`;}
 main.innerHTML=shell(title,subtitle,content,true);
 }else if(page==='conta/dados'){main.innerHTML=shell('Seus dados.','Mantenha seu nome atualizado.',`<form data-account-form="profile" class="profile-form">${field('Nome','name',currentUser.name,'text','required minlength="2" maxlength="100"')}${field('E-mail de acesso','email',currentUser.email,'email','disabled')}<p class="form-error" role="alert"></p><button class="btn dark">Salvar dados</button></form>`);}
 else{const orders=await api('orders');if(version!==routeVersion)return;main.innerHTML=shell('Seus pedidos.','Suas seleções de jeans, salvas para consultar depois.',orderCards(orders));}
 }catch(e){if(version===routeVersion)main.innerHTML=`<section class="info-page"><h1>Não foi possível carregar.</h1><p>${esc(e.message)}</p><button class="btn" data-retry>Tentar novamente</button></section>`;}};
window.addEventListener('hashchange',route);
document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('[data-account-form],[data-product],[data-status]'))return;e.preventDefault();const button=form.querySelector('button:not([type="button"])');button.disabled=true;const error=form.querySelector('.form-error');error.textContent='';try{const values=Object.fromEntries(new FormData(form));if(form.dataset.accountForm){const action=form.dataset.accountForm;const result=await api(action,action==='profile'?'PATCH':'POST',values);if(action!=='profile'){const confirmed=await api('session');if(!confirmed.user)throw new Error('O navegador não manteve seu login. Permita cookies para este endereço e tente novamente.');}currentUser=result.user;if(action==='profile'){toast('Dados atualizados.');}else{location.hash=form.dataset.admin==='true'?'admin':'conta';await route();if(sessionStorage.getItem('ms-save-after-login')){sessionStorage.removeItem('ms-save-after-login');renderCart();dialog.showModal();}}}else if(form.dataset.product){values.variants=[...form.querySelectorAll('.stock-row')].map(row=>({size:row.querySelector('[data-stock-size]').value,quantity:Number(row.querySelector('[data-stock-quantity]').value)}));values.inventoryVersion=Number(form.querySelector('[data-version]').dataset.version);await api('admin/products/'+form.dataset.product,'PATCH',values);await loadProducts();form.querySelector('[data-version]').dataset.version=products.find(p=>p.id===form.dataset.product).inventoryVersion;toast('Catálogo atualizado.');}else{await api('admin/orders/'+form.dataset.status,'PATCH',values);await route();toast('Situação atualizada.');}}catch(err){error.textContent=err.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;if(el.hasAttribute('data-retry'))route();if(el.hasAttribute('data-logout')){try{await api('logout','POST',{});currentUser=null;await route();}catch(err){toast(err.message);}}},false);
// Intercept review before the existing demo-only cart handler.
document.addEventListener('click',async e=>{const button=e.target.closest('[data-review],[data-save-order]');if(!button)return;e.stopImmediatePropagation();if(cart.reduce((s,i)=>s+i.qty,0)<6)return;button.disabled=true;try{const session=await api('session');currentUser=session.user;if(!currentUser){sessionStorage.setItem('ms-save-after-login','1');dialog.close();location.hash='conta';await route();return;}if(button.hasAttribute('data-review')){document.querySelector('#cart-body').innerHTML=`<div class="success"><h3>Salvar esta seleção?</h3><p>${cart.reduce((s,i)=>s+i.qty,0)} peças serão salvas na conta de ${esc(currentUser.name)}.</p><p>Pedido demonstrativo, sem cobrança ou envio. Ao confirmar, as unidades serão descontadas do estoque local.</p></div><button class="btn dark" data-save-order>Salvar pedido na minha conta</button><button class="btn outline" data-back-cart>Voltar às peças</button>`;}else{await api('orders','POST',{items:cart});cart=[];save();await loadProducts();dialog.close();location.hash='conta';await route();toast('Pedido demonstrativo salvo na sua conta.');}}catch(err){toast(err.message);}finally{button.disabled=false;}},true);
async function loadProducts(){const list=await api('products');products.splice(0,products.length,...list);}
loadProducts().then(()=>route()).catch(()=>{toast('Não foi possível conectar ao servidor local.');route();});
